\COPY db2_pdetcdfo (DCFCTR,DCFSUI,DCFUTI,DCFNLI,DCFSUC,DCFSSU,DCFFOU,DCFCLI,DCFART,DCFLIB,DCFQUC,DCFQUR,DCFQUL,DCFLSS,DCFLAA,DCFLMM,DCFLJJ,DCFPAC,DCFPRV,DCFREM,DCFRES,DCFUNV,DCFGRO,DCFSGR,DCFCVA,DCFCAN,DCFSTA,DCFSTB,DCFSTC,DCFSTF,DCFPSP,DCFNFA,DCFFSS,DCFFAA,DCFFMM,DCFFJJ,DCFCSS,DCFCAA,DCFCMM,DCFCJJ,DCFMSS,DCFMAA,DCFMMM,DCFMJJ,DCFRE) FROM '/odoo/data/install/db2/pdetcdfo_2016-01_2018-03.csv' WITH DELIMITER AS ',' HEADER CSV QUOTE AS '"' ENCODING 'latin-1';



